-- ================================================-- 016 - 修正角色权限配置-- 清理并重新配置各角色的菜单权限，确保普通员工和外请审核员看不到不该有的菜单-- ================================================-- 1. 清理 viewer（普通员工）角色的所有权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'viewer');-- 重新分配 viewer 角色权限（仅基础查看）INSERT INTO role_permissions (id, role_id, permission_id)SELECT UUID(), r.id, p.idFROM roles rCROSS JOIN permissions pWHERE r.code = 'viewer'  AND p.code IN (    'menu:daily', 'menu:yearly', 'menu:ingredients',    'menu:m-daily', 'menu:m-yearly', 'menu:m-query'  );-- 2. 清理 temp_auditor（外请审核员）角色的所有权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'temp_auditor');-- 重新分配 temp_auditor 角色权限INSERT INTO role_permissions (id, role_id, permission_id)SELECT UUID(), r.id, p.idFROM roles rCROSS JOIN permissions pWHERE r.code = 'temp_auditor'  AND p.code IN (    -- PC端菜单    'menu:temp-audit', 'menu:temp-assessments', 'menu:temp-stats',    -- 基础查看    'menu:daily', 'menu:m-daily',    -- 移动端    'menu:m-temp-audit', 'menu:m-temp-assessment', 'menu:m-temp-stats',    -- 操作权限    'action:temp-worker:manage', 'action:temp-position:manage',    'action:temp-auditor:manage', 'action:temp-assessment:manage',    'action:temp-stats:view'  );-- 3. 清理 temp_chairman（外请董事长）角色的所有权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'temp_chairman');-- 重新分配 temp_chairman 角色权限（只读）INSERT INTO role_permissions (id, role_id, permission_id)SELECT UUID(), r.id, p.idFROM roles rCROSS JOIN permissions pWHERE r.code = 'temp_chairman'  AND p.code IN (    'menu:temp-stats', 'menu:daily', 'menu:m-daily', 'menu:m-temp-stats'  );-- 4. 确保 finance 角色没有食材管理权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'finance')  AND permission_id IN (SELECT id FROM permissions WHERE code = 'menu:ingredient-manager');-- 5. 确保 boss 角色没有食材管理权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'boss')  AND permission_id IN (SELECT id FROM permissions WHERE code = 'menu:ingredient-manager');-- 6. 验证结果SELECT  r.code AS role_code,  r.name AS role_name,  p.code AS perm_code,  p.name AS perm_nameFROM roles rJOIN role_permissions rp ON r.id = rp.role_idJOIN permissions p ON rp.permission_id = p.idWHERE r.code IN ('viewer', 'temp_auditor', 'temp_chairman')  AND p.type = 'menu'ORDER BY r.code, p.sort_order;SELECT '016_fix_role_permissions.sql 执行完成' AS message;